// Build a Microsoft Graph $filter for messages that:
//  - arrived in the last 25 hours (overlap of 1h to be safe)
//  - haven't already been categorised as 'Invoices-Forwarded'
const since = new Date(Date.now() - 25 * 60 * 60 * 1000).toISOString();
const filter = `receivedDateTime ge ${since} and (categories/any(c:c eq 'Invoices-Forwarded') eq false)`;
return [{ json: { filter, since } }];

// One item per message arrives here. Normalise the fields the LLM needs.
const m = $input.first().json;
const senderEmail = m.from?.emailAddress?.address || '';
const senderName  = m.from?.emailAddress?.name || '';
return [{
  json: {
    messageId: m.id,
    subject: m.subject || '',
    senderEmail,
    senderName,
    receivedAt: m.receivedDateTime,
    bodyPreview: (m.bodyPreview || '').slice(0, 1500),
    hasAttachments: !!m.hasAttachments
  }
}];

// Parse the LLM's JSON response and merge with the message context.
const raw = $input.first().json.message?.content || $input.first().json.content || '{}';
let parsed = {};
try { parsed = JSON.parse(raw.trim().replace(/^```json|```$/g, '').trim()); }
catch (e) { parsed = { is_cost_doc: false, confidence: 0, reason: 'parse_failed: ' + e.message }; }

const src = $node['Normalise Message'].json;
return [{
  json: {
    ...src,
    classification: parsed,
    shouldForward: parsed.is_cost_doc === true && (parsed.confidence ?? 0) >= 0.7
  }
}];

