// Aggregate every item that flowed through forwarding into a single summary item.
const items = $input.all();
const forwarded = items.map(i => i.json).filter(j => j.shouldForward);
const lines = forwarded.map(j => {
  const c = j.classification || {};
  const supplier = c.supplier || j.senderName || j.senderEmail;
  const amount = c.amount_gbp != null ? `£${c.amount_gbp}` : '£?';
  return `• ${supplier} — ${amount} — "${j.subject}"`;
});
const summary = forwarded.length
  ? `Forwarded ${forwarded.length} invoice${forwarded.length === 1 ? '' : 's'} to Dext + ServiceM8:\n\n${lines.join('\n')}`
  : null;
return [{ json: { count: forwarded.length, summary, forwarded } }];
